UpdateInfo verifyManifest(const std::vector<unsigned char>&m,const std::vector<unsigned char>&s){if(m.size()>65536||!signatureOK(m,s))throw std::runtime_error(tr(TextId::S230));auto j=Json::parse(std::string(m.begin(),m.end()));auto v=Version::parse(j["version"].str()),cur=Version::parse(PET_VERSION),min=Version::parse(j["minVersion"].str());if(!v||!cur||!min||!(*cur<*v)||*cur<*min||j["schema"].num()!=1||j["arch"].str()!="windows-x64"||j["asset"].str()!="DesktopPet-windows-x64.zip")throw std::runtime_error(tr(TextId::S231));auto size=j["size"].num();auto h=j["sha256"].str();if(size<1||size>15*1024*1024||std::floor(size)!=size||h.size()!=64||h.find_first_not_of("0123456789abcdef")!=std::string::npos)throw std::runtime_error(tr(TextId::S232));checkTrustVersion(j);UpdateInfo info;info.version=j["version"].str();info.notes=j["notes"].str();info.size=size_t(size);info.manifest=m;info.signature=s;return info;}
std::vector<unsigned char> verifyPackage(const fs::path&stage,const UpdateInfo&info){auto b=readBytes(stage/L"package.zip",15*1024*1024);auto j=Json::parse(std::string(info.manifest.begin(),info.manifest.end()));if(b.size()!=info.size||sha256(b)!=j["sha256"].str())throw std::runtime_error(tr(TextId::S233));inspectZip(b);return b;}
bool UpdateClient::enabled()const{return std::string(PET_OWNER).size()&&std::string(PET_REPO).size()&&std::string(PET_PUBLIC_KEY).size()==128;}
