void UpdateClient::download(){auto next=latest();if(next.version.empty())return;work([this,next]{phase(UpdatePhase::Downloading,tr(TextId::S160));{std::lock_guard<std::mutex>lock(mutex);staged.clear();}auto dir=appData()/L"updates"/wide(randomId());fs::create_directories(dir);try{auto b=request(wide(next.base+"DesktopPet-windows-x64.zip"),next.size,cancelFlag,&progressFlag);atomicWrite(dir/L"package.zip",b.data(),b.size());atomicWrite(dir/L"update.json",next.manifest.data(),next.manifest.size());atomicWrite(dir/L"update.sig",next.signature.data(),next.signature.size());phase(UpdatePhase::Verifying,tr(TextId::S240));verifyPackage(dir,next);if(cancelFlag)throw std::runtime_error(tr(TextId::S220));std::lock_guard<std::mutex>lock(mutex);staged=dir;status=tr(TextId::S241);phaseFlag=UpdatePhase::Ready;progressFlag=100;}catch(...){std::error_code e;fs::remove_all(dir,e);throw;}});}
